package cn.local.tomorrow;
import android.app.*;import android.content.*;import android.os.*;import android.webkit.*;import org.json.*;
public final class BackgroundCheck {
 public interface Done{void finished(boolean success);}
 final Context c;final Done done;final Handler handler=new Handler(Looper.getMainLooper());SchoolClient school;WebView processor;JSONObject initial;boolean stopped=false;
 BackgroundCheck(Context context,Done callback){c=context;done=callback;}
 public void start(){try{if(!UserConsent.granted(c)){finish(false);return;}initial=StateStore.load(c);if(initial==null||!"school".equals(initial.getJSONObject("snapshot").getJSONObject("source").optString("kind"))){finish(false);return;}if(!CheckScheduler.enabled(c)){finish(false);return;}StateStore.log(c,"background-check start");school=new SchoolClient(c,new SchoolClient.Listener(){public void progress(String text){}public void loginRequired(WebView v){}public void portalEntered(){}public void success(JSONObject data){process(data);}public void failure(String text){try{if(text.contains("另一项")){finish(false);return;}process(new JSONObject().put("error",text));}catch(Exception e){finish(false);}}});school.start("background-"+System.currentTimeMillis(),true,initial.getJSONObject("snapshot").optJSONObject("studentProfile"));handler.postDelayed(()->{if(!stopped){StateStore.log(c,"background-check watchdog");finish(false);}},90000);}catch(Exception e){finish(false);}}
 void process(JSONObject data){if(stopped)return;CheckScheduler.markAttempt(c);processor=new WebView(c);StateStore.configure(processor);processor.setWebViewClient(StateStore.localAssets(c));processor.addJavascriptInterface(new Object(){@JavascriptInterface public void post(String action,String json){handler.post(()->message(action,json,data));}},"Android");processor.loadUrl("https://app.local/background.html");}
 void message(String action,String json,JSONObject data){if(stopped)return;try{if("ready".equals(action)){JSONObject latest=StateStore.load(c);processor.evaluateJavascript("window.processBackground("+latest+","+data+")",null);return;}JSONObject payload=new JSONObject(json);if("commit".equals(action)){
  JSONObject state=payload.getJSONObject("state"),notice=payload.optJSONObject("notice");boolean notified=false;
  // Commit first; the revision check preserves concurrent edits and read receipts.
  long revision=StateStore.save(c,state,payload.getLong("expectedRevision"));
  ScheduleWidgetProvider.updateAll(c);
  if(notice!=null)notified=notifyUser(1001,notice.optString("title"),notice.optString("body"),"changes");
  if(notified){JSONArray ids=notice.getJSONArray("ids"),events=state.getJSONArray("events");for(int n=0;n<events.length();n++){JSONObject e=events.getJSONObject(n);for(int k=0;k<ids.length();k++)if(e.optString("id").equals(ids.getString(k)))e.put("notifiedAt",new java.text.SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ssXXX",java.util.Locale.US).format(new java.util.Date()));}if(!notice.isNull("digestDate"))state.put("digestDate",notice.getString("digestDate"));try{StateStore.save(c,state,revision);ScheduleWidgetProvider.updateAll(c);}catch(Exception ignored){}}
  boolean success=payload.isNull("error");if(!success)notifyUser(2203,"江水课表需要你确认",payload.optString("error"),"check-errors");StateStore.log(c,"background-commit success="+success);finish(success);
 }else if("failure".equals(action)){notifyUser(2203,"江水课表未能确认更新",payload.optString("message"),"check-errors");finish(false);}}catch(Exception e){StateStore.log(c,"background-commit conflict-or-failure");notifyUser(2203,"后台核对暂未保存","本机课表正在变化，已有数据和修改均已保留","check-errors");finish(false);}}
 boolean notifyUser(int id,String title,String body,String channel){try{NotificationManager nm=c.getSystemService(NotificationManager.class);if(!nm.areNotificationsEnabled())return false;nm.createNotificationChannel(new NotificationChannel(channel,"changes".equals(channel)?"课表变化":"检查异常提醒",NotificationManager.IMPORTANCE_HIGH));nm.notify(id,NotificationCards.message(c,channel,title,body,"changes".equals(channel)?"课表变更":"需要确认",NotificationCards.openApp(c,id),false));return true;}catch(Exception e){return false;}}
 void finish(boolean success){if(stopped)return;stopped=true;CheckScheduler.recordResult(c,success);if(school!=null)school.destroy();if(processor!=null){processor.removeJavascriptInterface("Android");processor.destroy();processor=null;}done.finished(success);}
 public void stop(){if(stopped)return;stopped=true;if(school!=null)school.destroy();if(processor!=null){processor.removeJavascriptInterface("Android");processor.destroy();processor=null;}}
}
